parameters.content:
## MCP - Image OCR (RFC-014)

**Endpoint:** POST /webhook/image-ocr

**RFC-014 Input:**
```json
{
  "context": {
    "image_url": "https://..." OR "image_base64": "...",
    "file_type": "jpg"
  },
  "plugin_context": {
    "api_keys": { "mistral": "..." }
  }
}
```

**Legacy Input (also supported):**
```json
{
  "image_url": "https://...",
  "mistral_api_key": "..."
}
```

**Response:** OCR result with text and metadata

parameters.jsCode:
const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

// Validation - check both structures
const hasImage = !!(ctx.image_url || ctx.image_base64 || ctx.file_url || ctx.file_base64 || body.image_url || body.image_base64);
const mistralKey = body.mistral_api_key || ctx.mistral_api_key || body.plugin_context?.api_keys?.mistral || ctx.plugin_context?.api_keys?.mistral;
const hasMistralKey = !!mistralKey;

const errors = [];
if (!hasImage) errors.push('image_url ou image_base64 requis');
if (!hasMistralKey) errors.push('mistral_api_key requis');

// Fonction pour détecter le MIME type depuis les magic bytes base64
function detectMimeFromBase64(base64) {
  const prefix = base64.substring(0, 20);
  if (prefix.startsWith('/9j/')) return 'image/jpeg';
  if (prefix.startsWith('iVBOR')) return 'image/png';
  if (prefix.startsWith('R0lG')) return 'image/gif';
  if (prefix.startsWith('UklGR')) return 'image/webp';
  if (prefix.startsWith('Qk')) return 'image/bmp';
  return 'image/png';
}

// Fonction pour obtenir le MIME type depuis l'extension
function getMimeFromExtension(ext) {
  const map = {
    'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
    'png': 'image/png', 'gif': 'image/gif',
    'webp': 'image/webp', 'bmp': 'image/bmp',
    'tiff': 'image/tiff', 'tif': 'image/tiff'
  };
  return map[(ext || '').toLowerCase()] || null;
}

// Extract image - prefer context.* (RFC-014) over root level
const imageUrl_raw = ctx.image_url || ctx.file_url || body.image_url;
const imageBase64_raw = ctx.image_base64 || ctx.file_base64 || body.image_base64;
const fileType = ctx.file_type || body.file_type;

// Préparer l'image avec détection MIME intelligente
let imageUrl = '';
let detectedMime = 'image/png';

if (imageUrl_raw) {
  imageUrl = imageUrl_raw;
} else if (imageBase64_raw) {
  // 1. Essayer depuis file_type param
  if (fileType) {
    detectedMime = getMimeFromExtension(fileType) || 'image/png';
  } else {
    // 2. Détecter depuis magic bytes
    detectedMime = detectMimeFromBase64(imageBase64_raw);
  }
  imageUrl = 'data:' + detectedMime + ';base64,' + imageBase64_raw;
}

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    imageUrl: imageUrl,
    detectedMime: detectedMime,
    mistralApiKey: mistralKey,
    includeImages: body.include_images || ctx.include_images || false,
    source: imageUrl_raw ? 'url' : 'base64'
  }
}];

const input = $input.first().json;
const prevData = $('Extract Job ID').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Vérifier erreur
if (statusCode >= 400) {
  return [{
    json: {
      success: false,
      jobId: prevData.jobId,
      error: {
        code: statusCode,
        message: data.message || data.error?.message || 'Mistral API error',
        status: 'API_ERROR'
      }
    }
  }];
}

// Extraire le texte
const text = data.pages?.map(p => p.markdown).join('\n\n') || '';

return [{
  json: {
    success: true,
    jobId: prevData.jobId,
    data: {
      text: text,
      pages: data.pages || [],
      model: data.model || 'mistral-ocr-latest',
      source: prevData.source
    },
    meta: {
      provider: 'mistral',
      usage: {
        pages_processed: data.usage_info?.pages_processed || 1,
        doc_size_bytes: data.usage_info?.doc_size_bytes || 0
      }
    }
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

const input = $input.first().json;
const prevData = $('Validation').first().json;

// Extraire job_id de la réponse API ou utiliser un ID local
const data = input.body || input;
const jobId = data.job_id || data.id || ('job_' + Date.now().toString(36));

return [{
  json: {
    ...prevData,
    jobId: jobId
  }
}];

